<?php
require_once 'inc/db.php';require_once 'inc/auth.php';if((int)$_SESSION['role_id']!==1){http_response_code(403);die('Access denied.');}$msg='';
if(isset($_POST['toggle'])){$id=(int)$_POST['toggle'];if($id!==(int)$_SESSION['user_id']){$db->prepare('UPDATE tbl_users SET is_active=1-is_active WHERE user_id=?')->execute([$id]);audit_log($db,'USER_ACCESS_UPDATED','Access toggled for user ID '.$id);$msg='User access updated.';}}
$users=$db->query('SELECT u.*,r.role_name FROM tbl_users u JOIN tbl_roles r ON r.role_id=u.role_id ORDER BY u.created_at DESC')->fetchAll(PDO::FETCH_ASSOC);$page_title='Manage Users';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><section class="panel"><header class="panel-heading"><h2 class="panel-title"><i class="fa fa-users"></i> Users and Roles</h2></header><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Name</th><th>Contact</th><th>Role</th><th>Joined</th><th>Access</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?php echo e($u['firstname'].' '.$u['lastname']);?></strong><br><small>@<?php echo e($u['username']);?></small></td><td><?php echo e($u['email']);?><br><?php echo e($u['phone']);?></td><td><?php echo e($u['role_name']);?></td><td><?php echo date('d M Y',strtotime($u['created_at']));?></td><td><form method="post"><button name="toggle" value="<?php echo (int)$u['user_id'];?>" class="btn btn-xs btn-<?php echo $u['is_active']?'success':'danger';?>" <?php echo (int)$u['user_id']===(int)$_SESSION['user_id']?'disabled':'';?>><?php echo $u['is_active']?'Active':'Disabled';?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></section></div><?php include 'inc/scripts.php';?>
